<template><q-page class="q-pa-lg"><div class="text-h4 q-mb-lg">Narudžbe</div><q-table :rows="orders" :columns="columns" row-key="id_narudzba" :loading="loading"><template #body-cell-ukupno_sa_pdv="p"><q-td :props="p">{{ Number(p.value).toFixed(2) }} €</q-td></template><template #body-cell-status="p"><q-td :props="p"><q-badge :color="p.row.status_boja || 'primary'">{{p.row.status_naziv}}</q-badge></q-td></template><template #body-cell-akcije="p"><q-td :props="p"><q-select dense outlined :model-value="p.row.id_status_narudzbe" :options="statuses" option-label="naziv" option-value="id_status_narudzbe" emit-value map-options @update:model-value="v => updateStatus(p.row, v)"/></q-td></template></q-table></q-page></template>
<script setup>
import {onMounted,ref} from 'vue';import {useQuasar} from 'quasar';import {api} from 'boot/axios';const $q=useQuasar();const orders=ref([]);const statuses=ref([]);const loading=ref(false);const columns=[{name:'broj_narudzbe',label:'Broj',field:'broj_narudzbe',align:'left'},{name:'korisnik_ime',label:'Korisnik',field:'korisnik_ime'},{name:'ukupno_sa_pdv',label:'Ukupno',field:'ukupno_sa_pdv'},{name:'status',label:'Status',field:'status_naziv'},{name:'datum_kreiranja',label:'Datum',field:'datum_kreiranja'},{name:'akcije',label:'Promijeni status',field:'id_narudzba'}];async function load(){loading.value=true;try{const [o,s]=await Promise.all([api.get('/narudzbe',{params:{limit:100}}),api.get('/statusi')]);orders.value=o.data.data||[];statuses.value=s.data;}finally{loading.value=false;}}async function updateStatus(row,v){try{await api.put(`/narudzbe/${row.id_narudzba}/status`,{id_status_narudzbe:v});await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Promjena statusa nije uspjela.'});}}onMounted(load);
</script>
